export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model usuario
 * Persona con correo institucional (estudiante, docente o funcionario). Solo los administradores tienen contraseña.
 */
export type usuario = $Result.DefaultSelection<Prisma.$usuarioPayload>
/**
 * Model rol
 * Perfil funcional del sistema (p. ej. Administrador, Editor, Solo lectura).
 */
export type rol = $Result.DefaultSelection<Prisma.$rolPayload>
/**
 * Model permiso
 * Acción concreta que puede autorizarse (p. ej. sala.editar, faq.publicar).
 */
export type permiso = $Result.DefaultSelection<Prisma.$permisoPayload>
/**
 * Model rol_permiso
 * Relación N:M entre roles y permisos.
 */
export type rol_permiso = $Result.DefaultSelection<Prisma.$rol_permisoPayload>
/**
 * Model usuario_rol
 * Relación N:M entre usuarios y roles.
 */
export type usuario_rol = $Result.DefaultSelection<Prisma.$usuario_rolPayload>
/**
 * Model sesion_admin
 * Sesión iniciada en la aplicación de escritorio administrativa (se puede revocar).
 */
export type sesion_admin = $Result.DefaultSelection<Prisma.$sesion_adminPayload>
/**
 * Model escuela
 * Escuela o unidad académica que agrupa carreras.
 */
export type escuela = $Result.DefaultSelection<Prisma.$escuelaPayload>
/**
 * Model carrera
 * Carrera o programa que se imparte en la institución.
 */
export type carrera = $Result.DefaultSelection<Prisma.$carreraPayload>
/**
 * Model estudiante
 * Datos académicos de un usuario que es estudiante (extensión 1:1 de usuario).
 */
export type estudiante = $Result.DefaultSelection<Prisma.$estudiantePayload>
/**
 * Model sede
 * Sede o campus.
 */
export type sede = $Result.DefaultSelection<Prisma.$sedePayload>
/**
 * Model edificio
 * Edificio o torre dentro de la sede.
 */
export type edificio = $Result.DefaultSelection<Prisma.$edificioPayload>
/**
 * Model piso
 * Piso de un edificio, con referencia a su plano SVG.
 */
export type piso = $Result.DefaultSelection<Prisma.$pisoPayload>
/**
 * Model tipo_espacio
 * Catálogo de tipos de espacio (sala, baño, escalera, ascensor, terraza, oficina, etc.).
 */
export type tipo_espacio = $Result.DefaultSelection<Prisma.$tipo_espacioPayload>
/**
 * Model espacio
 * Espacio físico del plano (sala, oficina, baño, etc.). Se vincula al elemento del SVG.
 */
export type espacio = $Result.DefaultSelection<Prisma.$espacioPayload>
/**
 * Model espacio_alias
 * Nombres alternativos de un espacio, para que la búsqueda lo encuentre (p. ej. "pañol").
 */
export type espacio_alias = $Result.DefaultSelection<Prisma.$espacio_aliasPayload>
/**
 * Model equipamiento
 * Equipamiento disponible en un espacio (proyector, computadores, pizarra, etc.).
 */
export type equipamiento = $Result.DefaultSelection<Prisma.$equipamientoPayload>
/**
 * Model area_institucional
 * Área institucional de atención (financiamiento, informática, asuntos estudiantiles, etc.). El directorio del tótem se organiza por áreas, no por personas.
 */
export type area_institucional = $Result.DefaultSelection<Prisma.$area_institucionalPayload>
/**
 * Model tramite
 * Trámite administrativo que el estudiante puede consultar.
 */
export type tramite = $Result.DefaultSelection<Prisma.$tramitePayload>
/**
 * Model tramite_paso
 * Paso ordenado de la guía de un trámite.
 */
export type tramite_paso = $Result.DefaultSelection<Prisma.$tramite_pasoPayload>
/**
 * Model tramite_requisito
 * Documento o requisito que el estudiante debe presentar en un trámite.
 */
export type tramite_requisito = $Result.DefaultSelection<Prisma.$tramite_requisitoPayload>
/**
 * Model categoria_faq
 * Categoría temática de las preguntas frecuentes.
 */
export type categoria_faq = $Result.DefaultSelection<Prisma.$categoria_faqPayload>
/**
 * Model pregunta_frecuente
 * Pregunta frecuente y su respuesta, gestionada desde la app de escritorio.
 */
export type pregunta_frecuente = $Result.DefaultSelection<Prisma.$pregunta_frecuentePayload>
/**
 * Model intento_autenticacion
 * Verificación de identidad por código de un solo uso enviado al correo institucional.
 */
export type intento_autenticacion = $Result.DefaultSelection<Prisma.$intento_autenticacionPayload>
/**
 * Model enrolamiento
 * Proceso de enrolamiento fotográfico de un usuario (estudiante, docente o funcionario). Módulo opcional.
 */
export type enrolamiento = $Result.DefaultSelection<Prisma.$enrolamientoPayload>
/**
 * Model captura_facial
 * Resultado de la validación de la fotografía con Google Vision AI. La imagen es un dato biométrico y se elimina; solo permanece el resultado.
 */
export type captura_facial = $Result.DefaultSelection<Prisma.$captura_facialPayload>
/**
 * Model totem
 * Tótem físico instalado en la sede.
 */
export type totem = $Result.DefaultSelection<Prisma.$totemPayload>
/**
 * Model aviso
 * Aviso institucional publicado desde el panel administrativo.
 */
export type aviso = $Result.DefaultSelection<Prisma.$avisoPayload>
/**
 * Model aviso_totem
 * Tótems en los que se muestra cada aviso (N:M).
 */
export type aviso_totem = $Result.DefaultSelection<Prisma.$aviso_totemPayload>
/**
 * Model configuracion_sistema
 * Parámetros de la instalación: identidad de la institución (nombre, logo, colores, dominios de correo), módulo de enrolamiento y tiempos de operación.
 */
export type configuracion_sistema = $Result.DefaultSelection<Prisma.$configuracion_sistemaPayload>
/**
 * Model registro_auditoria
 * Bitácora de acciones realizadas en el panel administrativo.
 */
export type registro_auditoria = $Result.DefaultSelection<Prisma.$registro_auditoriaPayload>
/**
 * Model registro_consulta
 * Consultas hechas en el tótem; permite medir uso y detectar búsquedas sin resultado.
 */
export type registro_consulta = $Result.DefaultSelection<Prisma.$registro_consultaPayload>
/**
 * Model registro_error
 * Fallas de los servicios externos (Google Vision AI, correo, sistema de enrolamiento); permite investigar incidentes sin bloquear el resto del tótem.
 */
export type registro_error = $Result.DefaultSelection<Prisma.$registro_errorPayload>

